\begin{ex}%[9H4N2-4]
\immini[thm]{
Cho hình vẽ sau. Khẳng định nào sau đây là đúng

\choice
{  $AC=BC.\sin C$ }
   { $AB=AC.\cot C$  }
     { \True  $AB=BC.\cos B$ }
    { $AC=AB.\sin B$ }
}{
\begin{tikzpicture}[scale=0.65, font=\footnotesize, line cap=round, line join=round]
        % Tọa độ cho tam giác vuông
        \coordinate (A) at (0, 0);
        \coordinate (B) at (4, 0);
        \coordinate (C) at (0, 3);

        % Vẽ các cạnh của tam giác
        \draw[thick] (A) -- (B) -- (C) -- cycle;

        % Ghi nhãn các điểm
        \node[below left] at (A) {$A$};
        \node[below right] at (B) {$B$};
        \node[above left] at (C) {$C$};

        % Vẽ dấu vuông tại điểm A
        \draw (0,0) rectangle +(0.3,0.3);
    \end{tikzpicture}
}
