\coordinate (C) at (0,2.55);
\draw[thick] (A) -- (B) -- (C) -- cycle;
\draw[thin] ($(A)!0.22cm!(C)$) -- ($($(A)!0.22cm!(C)$)+($(A)!0.22cm!(B)$)-(A)$) -- ($(A)!0.22cm!(B)$);
\draw[blue!75!black, thin] let \p1 = ($(A)-(B)$), \p2 = ($(C)-(B)$) in ($(B) + ({atan2(\y1,\x1)}:0.48)$) arc ({atan2(\y1,\x1)}:{atan2(\y2,\x2)}:0.48);
\draw[red!75!black, thin] let \p1 = ($(A)-(C)$), \p2 = ($(B)-(C)$) in ($(C) + ({atan2(\y1,\x1)}:0.48)$) arc ({atan2(\y1,\x1)}:{atan2(\y2,\x2)}:0.48);
